package com.example.dsatracker.mapper;import com.example.dsatracker.dto.SubmissionRequestDTO;import com.example.dsatracker.dto.SubmissionResponseDTO;import com.example.dsatracker.model.Submission;import java.time.LocalDateTime;public class SubmissionMapper {    private SubmissionMapper() {    }    public static Submission toEntity(            SubmissionRequestDTO request) {        return Submission.builder()                .attempts(request.getAttempts())                .timeTaken(request.getTimeTaken())                .confidenceScore(request.getConfidenceScore())                .solutionViewed(request.getSolutionViewed())                .timeAway(request.getTimeAway())                .solvedOn(LocalDateTime.now())                .build();    }    public static SubmissionResponseDTO toResponse(            Submission submission) {        return SubmissionResponseDTO.builder()                .id(submission.getId())                .problemId(submission.getProblem().getId())                .attempts(submission.getAttempts())                .timeTaken(submission.getTimeTaken())                .confidenceScore(submission.getConfidenceScore())                .solutionViewed(submission.getSolutionViewed())                .timeAway(submission.getTimeAway())                .solvedOn(submission.getSolvedOn())                .nextRevision(submission.getNextRevision())                .build();    }}